    /// <summary>
    /// The project's own shaders, discovered from the files: every *.shader under NocPaths.ShadersDir (recursive, so the beat
    /// builders' Shaders/Beats/ is covered) and the name of its first 'Shader "..."' declaration. Read from the text, not from
    /// the imported Shader object, so a shader whose ShaderLab fails to parse is still listed (and then fails Validate).
    /// </summary>
    public static class ShaderCatalog
    {
        static readonly System.Text.RegularExpressions.Regex Decl =
            new System.Text.RegularExpressions.Regex(@"^\s*Shader\s+""([^""]+)""", System.Text.RegularExpressions.RegexOptions.Multiline);

        public struct Entry { public string name, assetPath; }

        /// <summary>Every .shader file under ShadersDir with its declared name (null when none is found), sorted by asset path.</summary>
        public static List<Entry> All()
        {
            var list = new List<Entry>();
            string root = NocPaths.Abs(NocPaths.ShadersDir);
            if (!Directory.Exists(root)) return list;
            var files = Directory.GetFiles(root, "*.shader", SearchOption.AllDirectories);
            Array.Sort(files, StringComparer.Ordinal);
            foreach (var f in files)
            {
                string rel = NocPaths.ShadersDir + "/" + f.Substring(root.Length).TrimStart('\\', '/').Replace('\\', '/');
                string text;
                try { text = File.ReadAllText(f); } catch { text = ""; }
                var m = Decl.Match(text);
                list.Add(new Entry { name = m.Success ? m.Groups[1].Value : null, assetPath = rel });
            }
            return list;
        }

        /// <summary>The declared names that start with NocPaths.ShaderNamePrefix (unique, ordinal order).</summary>
        public static string[] Names()
        {
            var set = new SortedSet<string>(StringComparer.Ordinal);
            foreach (var e in All())
                if (e.name != null && e.name.StartsWith(NocPaths.ShaderNamePrefix, StringComparison.Ordinal)) set.Add(e.name);
            var arr = new string[set.Count];
            set.CopyTo(arr);
            return arr;
        }

        /// <summary>Asset path of the file that declares the shader name (null when no file does).</summary>
        public static string PathOf(string shaderName)
        {
            foreach (var e in All()) if (e.name == shaderName) return e.assetPath;
            return null;
        }

        /// <summary>The shader asset by declared name: the file's imported Shader first (works for a shader with errors), then Shader.Find.</summary>
        public static Shader Load(string shaderName)
        {
            string path = PathOf(shaderName);
            var sh = path != null ? AssetDatabase.LoadAssetAtPath<Shader>(path) : null;
            return sh != null ? sh : Shader.Find(shaderName);
        }
    }

    /// <summary>"[NOC] ..." logging; problems are logged as "[NOC-FAIL] ..." and collected so batch methods exit non-zero.</summary>
    public static class NocLog
    {
        public const string Prefix = "[NOC] ";
        public const string FailPrefix = "[NOC-FAIL] ";

        public static void Info(string msg) => Debug.Log(Prefix + msg);
        public static void Warn(string msg) => Debug.LogWarning(Prefix + "WARNING " + msg);

        /// <summary>Logs an error and records it in the problem list (may be null).</summary>
        public static void Problem(List<string> problems, string msg)
        {
            Debug.LogError(FailPrefix + msg);
            if (problems != null) problems.Add(msg);
        }

        /// <summary>Batch logs: no stack traces on plain log lines (keeps the logs readable), and the invariant culture on the
        /// batch thread so every [NOC] line prints '.' decimals on any Windows locale (audit S3 item 14; this machine is ru-RU).</summary>
        public static void QuietStackTraces()
        {
            System.Threading.Thread.CurrentThread.CurrentCulture = System.Globalization.CultureInfo.InvariantCulture;
            System.Threading.Thread.CurrentThread.CurrentUICulture = System.Globalization.CultureInfo.InvariantCulture;
            Application.SetStackTraceLogType(LogType.Log, StackTraceLogType.None);
            Application.SetStackTraceLogType(LogType.Warning, StackTraceLogType.None);
        }
    }

    public static class EditorUtil
    {
        /// <summary>Resolves a type by full name across every loaded assembly.</summary>
        public static Type FindType(string fullName)
        {
            var asms = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < asms.Length; i++)
            {
                Type t = null;
                try { t = asms[i].GetType(fullName, false); } catch { /* dynamic or broken assembly */ }
                if (t != null) return t;
            }
            return null;
        }

        /// <summary>Adds (or returns the existing) component of the named type; logs a problem if the type is missing.</summary>
        public static Component AddComponentByName(GameObject go, string fullName, List<string> problems)
        {
            var t = FindType(fullName);
            if (t == null || !typeof(Component).IsAssignableFrom(t))
            {
                NocLog.Problem(problems, FormattableString.Invariant($"scene: component type '{fullName}' not found on '{go.name}'"));
                return null;
            }
            var c = go.GetComponent(t);
            if (c == null) c = go.AddComponent(t);
            if (c == null) NocLog.Problem(problems, FormattableString.Invariant($"scene: AddComponent({fullName}) failed on '{go.name}'"));
            return c;
        }

        /// <summary>Creates every missing folder of an asset path like "Assets/_Game/Materials".</summary>
        public static void EnsureFolder(string assetFolder)
        {
            assetFolder = assetFolder.TrimEnd('/');
            if (AssetDatabase.IsValidFolder(assetFolder)) return;
            int slash = assetFolder.LastIndexOf('/');
            string parent = assetFolder.Substring(0, slash);
            string leaf = assetFolder.Substring(slash + 1);
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, leaf);
        }

        /// <summary>The single object stored in a ProjectSettings/*.asset file (GraphicsSettings, TagManager, ...).</summary>
        public static Object LoadProjectSettingsObject(string projectSettingsPath)
        {
            var all = AssetDatabase.LoadAllAssetsAtPath(projectSettingsPath);
            return all != null && all.Length > 0 ? all[0] : null;
        }

        public static string AssetPathOf(Object o) => o != null ? AssetDatabase.GetAssetPath(o) : "";

        /// <summary>Writes a text file only when its content changed (no needless reimport); true when written.</summary>
        public static bool WriteTextIfChanged(string assetPath, string text)
        {
            string abs = NocPaths.Abs(assetPath);
            if (File.Exists(abs) && File.ReadAllText(abs) == text) return false;
            Directory.CreateDirectory(Path.GetDirectoryName(abs));
            File.WriteAllText(abs, text, new System.Text.UTF8Encoding(false));
            return true;
        }
    }
}
